param([string]$ProjectRoot = (Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference='Stop'
if([Threading.Thread]::CurrentThread.ApartmentState-ne[Threading.ApartmentState]::STA){throw 'Run with powershell.exe -STA.'}
$halcon='C:\Program Files\MVTec\HALCON-20.11-Progress';$env:PATH=(Join-Path $halcon 'bin\x64-win64')+';'+$env:PATH
Add-Type -AssemblyName PresentationFramework
[Reflection.Assembly]::LoadFrom((Join-Path $halcon 'bin\dotnet35\halcondotnet.dll'))|Out-Null
$assembly=[Reflection.Assembly]::LoadFrom((Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'))
function Assert([bool]$ok,[string]$message){if(-not$ok){throw "Assertion failed: $message"}}
$temp=Join-Path ([IO.Path]::GetTempPath()) ('halcon-s75-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$mainType=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$pointType=$assembly.GetType('HalconWinFormsDemo.Models.VmPoint2D',$true);$ellipseType=$assembly.GetType('HalconWinFormsDemo.Models.VmEllipse2D',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$static=[Reflection.BindingFlags]'Static,Public'
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$mainType.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
function F([string]$name){$f=$mainType.GetField($name,$all);if($null-eq$f){throw "Missing field $name"};$v=$f.GetValue($window);Write-Output -NoEnumerate $v}
function M([string]$name,[object[]]$invokeArgs=@()){try{$m=@($mainType.GetMethods($private)|Where-Object Name -eq $name|Where-Object{$_.GetParameters().Count-eq$invokeArgs.Count}|Select-Object -First 1);if($null-eq$m){throw "Missing method $name/$($invokeArgs.Count)"};$m.Invoke($window,$invokeArgs)}catch [Reflection.TargetInvocationException]{throw $_.Exception.InnerException}}
function Tool([string]$kind,[string]$name){$mainType.GetMethod('CreateFlowTool',$private).Invoke($window,[object[]]@([Enum]::Parse($kindType,$kind),$name,$true,$null))}
function Out($tool,[string]$port){$value=$null;if(-not$tool.TryGetOutputValue($port,[ref]$value)){throw "Missing output $port"};Write-Output -NoEnumerate $value}
function Point([double]$row,[double]$column,[string]$ctx='S75.Image'){$pointType.GetMethod('CreateImagePixel',$static).Invoke($null,[object[]]@($row,$column,$ctx))}
function Ellipse([double]$row,[double]$column,[double]$phi,[double]$r1,[double]$r2,[string]$ctx='S75.Image'){$ellipseType.GetMethod('CreateImagePixel',$static).Invoke($null,[object[]]@($row,$column,$phi,$r1,$r2,$ctx))}
function Execute($tool){M 'ExecuteFlowTool' @($tool,'S75 smoke')}

try{
  # A: aggregate anchors reuse real typed ports, exact selection, real binding, multi-port rejection and clear/undo.
  $flow=F 'flowTools';$imageSource=Tool ImageSource 'S75 Image Source';$imageTarget=Tool ImageChannel 'S75 Image Target';$imageDiff=Tool ImageDifference 'S75 Two Inputs';$flow.Add($imageSource);$flow.Add($imageTarget);$flow.Add($imageDiff);M 'RefreshFlowPortVisualization'|Out-Null
  Assert(($imageSource.GraphHeight-eq68-or$imageSource.GraphHeight-eq32)-and($imageTarget.GraphHeight-eq68-or$imageTarget.GraphHeight-eq32)) ('S75 aggregate anchors did not remain compatible with the S76 task-lens 68/32 card states: '+$imageSource.GraphHeight+'/'+$imageTarget.GraphHeight)
  $flyout=F 'FlowAggregatePortFlyoutS75';Assert($flyout.Visibility.ToString()-eq'Collapsed') 'Aggregate port flyout is permanently exposed'
  M 'OpenFlowAggregatePortFlyoutS75' @($imageSource,'OUT')|Out-Null;$items=F 'aggregatePortFlyoutItemsS75';Assert($flyout.Visibility.ToString()-eq'Visible'-and$items.Count-gt1) 'Output aggregate anchor did not open exact multi-port list'
  $sourceImage=@($imageSource.FlowOutputPorts|Where-Object{$_.PortName-eq'Image'})[0];$sourceImage=$sourceImage.PSObject.BaseObject;$row=New-Object Windows.Controls.Border;$row=$row.PSObject.BaseObject;$row.Tag=$sourceImage;M 'SelectAggregatePortS75' @($sourceImage,$row,[Windows.Point]::new(100,100),$true)|Out-Null
  $resolveArgs=[object[]]@($imageTarget,'IN',$null);$resolved=M 'ResolveAggregateHoverPortS75' $resolveArgs;$resolved=$resolved.PSObject.BaseObject;Assert($null-ne$resolved-and$resolved.PortName-eq'Image'-and[string]::IsNullOrWhiteSpace([string]$resolveArgs[2])) 'Single compatible aggregate IN did not resolve exact Image port'
  $applyArgs=[object[]]@($sourceImage,$resolved,$null);$applied=M 'TryApplyFlowPortBinding' $applyArgs;Assert($applied-and$imageTarget.GetInputBinding('Image').SourceToolId-eq$imageSource.ToolId) 'Aggregate anchor did not write real InputBindings'
  M 'CancelFlowPortDrag' @($null,$false)|Out-Null;M 'RefreshFlowPortVisualization'|Out-Null
  M 'SelectAggregatePortS75' @($sourceImage,$row,[Windows.Point]::new(100,100),$true)|Out-Null;$multiArgs=[object[]]@($imageDiff,'IN',$null);$multi=M 'ResolveAggregateHoverPortS75' $multiArgs;Assert($null-eq$multi-and([string]$multiArgs[2])-match'2'-and([string]$multiArgs[2])-match'IN') 'Ambiguous aggregate target silently guessed an input port'
  M 'CancelFlowPortDrag' @($null,$false)|Out-Null;M 'RefreshFlowPortVisualization'|Out-Null
  $targetChip=@($imageTarget.FlowInputPorts|Where-Object{$_.PortName-eq'Image'})[0];$targetChip=$targetChip.PSObject.BaseObject;$clearButton=New-Object Windows.Controls.Button;$clearButton=$clearButton.PSObject.BaseObject;$clearButton.Tag=$targetChip;$mouse=New-Object Windows.Input.MouseButtonEventArgs([Windows.Input.Mouse]::PrimaryDevice,0,[Windows.Input.MouseButton]::Left);$mouse=$mouse.PSObject.BaseObject;$mouse.RoutedEvent=[Windows.UIElement]::MouseLeftButtonDownEvent;M 'FlowAggregatePortClearButton_MouseLeftButtonDownS75' @($clearButton,$mouse)|Out-Null;Assert($null-eq$imageTarget.GetInputBinding('Image')) 'Aggregate input clear did not remove real binding'
  M 'UndoFlowEditButton_Click' @($null,$null)|Out-Null;$imageTarget=@($flow|Where-Object{$_.ToolId-eq$imageTarget.ToolId})[0];Assert($null-ne$imageTarget.GetInputBinding('Image')) 'Aggregate binding change did not enter undo history'

  # B: typed Point2D + Ellipse2D -> HALCON distance_pc -> typed/numeric/XLD outputs.
  $pointSource=Tool PointSetGeometryStatistics 'S75 Point Source';$ellipseSource=Tool TypedPointSetEllipseFittingMeasurement 'S75 Ellipse Source';$measure=Tool PointToEllipseDistanceMeasurement 'S75 Point Ellipse';$judge=Tool NumericJudge 'S75 Distance Judge';$flow.Add($pointSource);$flow.Add($ellipseSource);$flow.Add($measure);$flow.Add($judge)
  $measure.SetInputBinding('Point',$pointSource.ToolId,'Centroid');$measure.SetInputBinding('Ellipse',$ellipseSource.ToolId,'MainEllipse');$judge.SetInputBinding('Value',$measure.ToolId,'Distance');$judge.InputToolId=$measure.ToolId;$judge.InputPortName='Distance';$judge.NumericLowerLimit=19.5;$judge.NumericUpperLimit=20.5
  $phi=[Math]::PI/6;$ellipse=Ellipse 100 150 $phi 60 30;$ellipseSource.SetOutputValue('MainEllipse',$ellipse);$ellipseSource.ResultCode='OK'
  $outside=Point (100-80*[Math]::Sin($phi)) (150+80*[Math]::Cos($phi));$pointSource.SetOutputValue('Centroid',$outside);$pointSource.ResultCode='OK';$record=Execute $measure
  $distance=[double](Out $measure Distance);$signed=[double](Out $measure SignedDistance);$norm=[double](Out $measure NormalizedRadius);$closest=Out $measure ClosestPoint;$xld=Out $measure XLD
  Assert($record.ResultCode-eq'OK'-and(Out $measure Relation)-eq'Outside'-and[math]::Abs($distance-20)-lt0.15-and[math]::Abs($signed-20)-lt0.15-and[math]::Abs($norm-1.333333)-lt0.0001) ('Rotated outside point ellipse distance is wrong: relation='+(Out $measure Relation)+', distance='+$distance+', signed='+$signed+', normalized='+$norm)
  $initialXldCount=$xld.ObjectCount;Assert($closest.GetValidationError()-eq''-and$initialXldCount-ge4) 'Typed closest point or managed XLD missing';Execute $judge|Out-Null;Assert($judge.ResultCode-eq'OK') 'Distance did not drive NumericJudge'
  $oldXld=$xld;$center=Point 100 150;$pointSource.SetOutputValue('Centroid',$center);Execute $measure|Out-Null;Assert((Out $measure Relation)-eq'Inside'-and[double](Out $measure SignedDistance)-lt0-and[math]::Abs([double](Out $measure NormalizedRadius))-lt1e-9-and$oldXld.IsDisposed) 'Center-point inside semantics or old XLD cleanup failed'
  $boundary=Point (100-60*[Math]::Sin($phi)) (150+60*[Math]::Cos($phi));$pointSource.SetOutputValue('Centroid',$boundary);Execute $measure|Out-Null;Assert((Out $measure Relation)-eq'OnBoundary'-and[math]::Abs([double](Out $measure SignedDistance))-lt1e-9-and[double](Out $measure Distance)-lt0.1) 'Boundary semantics failed'
  $quadrant=Point (100-42*[Math]::Sin($phi)+18*[Math]::Cos($phi)) (150+42*[Math]::Cos($phi)+18*[Math]::Sin($phi));$pointSource.SetOutputValue('Centroid',$quadrant);Execute $measure|Out-Null;Assert((Out $measure Relation)-eq'Inside'-and[double](Out $measure NormalAngle)-ge-180-and[double](Out $measure NormalAngle)-le180) 'Rotated quadrant/normal angle semantics failed'
  $nearCircle=Ellipse 80 90 0.7 30 29.999;$ellipseSource.SetOutputValue('MainEllipse',$nearCircle);$pointSource.SetOutputValue('Centroid',(Point 80 130));Execute $measure|Out-Null;Assert((Out $measure Relation)-eq'Outside'-and[double](Out $measure Distance)-gt9.9) 'Near-circle ellipse semantics failed'
  $pointSource.ResultCode='NG';$staleRejected=$false;try{Execute $measure|Out-Null}catch{$staleRejected=$true};Assert($staleRejected) 'Stale Point2D source was accepted';$pointSource.ResultCode='OK'
  $ellipseSource.SetOutputValue('MainEllipse',(Ellipse 80 90 0 30 20 'Other.Image'));$mixedRejected=$false;try{Execute $measure|Out-Null}catch{$mixedRejected=$true};Assert($mixedRejected) 'Mixed coordinate contexts were accepted'
  $invalid=[Activator]::CreateInstance($ellipseType);$invalid.CenterRow=80;$invalid.CenterColumn=90;$invalid.Radius1=30;$invalid.Radius2=0;$invalid.CoordinateContext='ImagePixel';$invalid.CoordinateContextId='S75.Image';$invalid.IsValid=$true;$ellipseSource.SetOutputValue('MainEllipse',$invalid);$invalidRejected=$false;try{Execute $measure|Out-Null}catch{$invalidRejected=$true};Assert($invalidRejected) 'Degenerate ellipse was accepted'
  $measure.Parameters.PointEllipseBoundaryTolerance=0;$paramError=$measure.Parameters.Validate([Enum]::Parse($kindType,'PointToEllipseDistanceMeasurement'));Assert(-not[string]::IsNullOrWhiteSpace($paramError)) 'Invalid boundary tolerance accepted';$measure.Parameters.PointEllipseBoundaryTolerance=0.4;$measure.Parameters.PointEllipseOverlayCrossSize=12;$measure.Parameters.PointEllipseContourResolution=0.2
  (F 'FlowToolList').SelectedItem=$measure;M 'LoadDockConfigurationDraft' @($measure)|Out-Null;Assert((F 'DockPointToEllipseDistancePanel').Visibility.ToString()-eq'Visible'-and(F 'DockPointEllipseBoundaryToleranceTextBox').Text-eq'0.4') 'Dock point-ellipse configuration did not synchronize'
  $recipe=M 'CaptureRecipe';$saved=@($recipe.ToolFlow|Where-Object{$_.ToolId-eq$measure.ToolId})[0];Assert($saved.Parameters.PointEllipseBoundaryTolerance-eq0.4-and$saved.Parameters.PointEllipseContourResolution-eq0.2) 'Point-ellipse parameters did not persist in recipe'
  $catalog=F 'toolCatalog';$ellipseKind=[Enum]::Parse($kindType,'PointToEllipseDistanceMeasurement');Assert($catalog.Count-eq[Enum]::GetValues($kindType).Count-and@($catalog|Where-Object{$_.Kind-eq$ellipseKind}).Count-eq1) 'S75 tool is not discoverable in the current complete catalog'
  $xaml=Get-Content (Join-Path $ProjectRoot 'MainWindow.xaml') -Raw;Assert($xaml-match'FlowAggregatePortFlyoutS75'-and$xaml-match'FlowAggregateAnchor_MouseLeftButtonDownS75'-and$xaml-notmatch'StrokeDashArray="7,4"') 'S75 aggregate anchor UI or simple drag line missing';Assert(@([regex]::Matches($xaml,'\bVM\b|VisionMaster')).Count-eq0) 'Visible XAML still exposes VM/VisionMaster branding'
  Write-Output ('S75_AGGREGATE_ANCHORS_POINT_ELLIPSE=PASS; Catalog=' + $catalog.Count + '; OutsideDistance='+$distance.ToString('0.###',[Globalization.CultureInfo]::InvariantCulture)+'; NormalizedRadius='+$norm.ToString('0.######',[Globalization.CultureInfo]::InvariantCulture)+'; XLD='+$initialXldCount+'')
}
finally{
  try{$mainType.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close()}catch{}
  if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
}
